// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    address owner;

    function setUp() public { c = new MultiplicatorX4(); owner = address(this); }

    function testFuzz_property(uint256 value) public {
        vm.assume(value <= 1 ether);

        Reverter r = new Reverter();

        vm.deal(address(this), value);

        bool ok;
        bytes memory data = "";
        try c.Command{value: value}(address(r), data) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}
